def q(s):
    return json.dumps(s, ensure_ascii=False)

def words(s):
    return re.findall(r"[\wÀ-ÿ'’.-]+", s)

def fm(data):
    lines = ['---']
    for key in ['title','slug','urlSlug','locale','translationKey','metaTitle','metaDescription','category']:
        lines.append(f'{key}: {q(data[key])}')
    lines.append('tags:')
    for tag in data['tags']:
        lines.append(f'  - {q(tag)}')
    for key in ['date','updatedDate']:
        lines.append(f'{key}: {data[key]}')
    lines.append(f'readingTime: {data["readingTime"]}')
    for key in ['excerpt','heroImage','imageAlt','articleType','heroCaption','heroCredit','heroSource']:
        lines.append(f'{key}: {q(data[key])}')
    if data.get('heroLicense'):
        lines.append(f'heroLicense: {q(data["heroLicense"])}')
    lines.extend(['heroWidth: 1600','heroHeight: 900','featured: false','sources:'])
    for src in data['sources']:
        lines.append(f'  - label: {q(src["label"])}')
        lines.append(f'    url: {q(src["url"])}')
    lines.append('disclaimer: true')
    lines.append('---')
    return '\n'.join(lines)

